parameters.jsCode:
const input = $input.first().json;
const body = input.body || input;

const text = body.text || "";
const sender = body.sender || "Unknown";

const fileUrl = body.file_url || null;
const fileType = body.file_type || "";
const fileName = body.file_name || "";

const isPdf = fileType === "application/pdf" || fileName.toLowerCase().endsWith(".pdf");
const isImage = fileType.startsWith("image/") || [".png", ".jpg", ".jpeg", ".webp"].some(ext => fileName.toLowerCase().endsWith(ext));

return [
  {
    json: {
      sender,
      message: text,
      file_url: fileUrl,
      file_type: fileType,
      file_name: fileName,
      hasPdf: isPdf,
      hasImage: isImage,
      messageId: body.messageId || "",
      timestamp: body.timestamp || new Date().toISOString()
    }
  }
];

const data = $input.first().json;

let inputType = "text";
if (data.hasPdf) inputType = "pdf";
else if (data.hasImage) inputType = "image";

return [
  {
    json: {
      ...data,
      inputType
    }
  }
];

const item = $input.first().json;

// Mock PDF text extraction for POC.
// Replace later with real PDF text extraction.
const pdfText = "";

return [
  {
    json: {
      ...item,
      pdf_text: pdfText,
      pdf_text_found: pdfText.trim().length > 0
    }
  }
];

const item = $input.first().json;

// Mock OCR for scanned PDFs.
// Replace later with real OCR.
return [
  {
    json: {
      ...item,
      ocr_text: "Extracted text from scanned PDF via OCR"
    }
  }
];

const item = $input.first().json;

// Mock OCR for image files.
// Replace later with real OCR.
return [
  {
    json: {
      ...item,
      ocr_text: "Extracted text from image via OCR"
    }
  }
];

const prev = $input.first().json;

const extractedText = [
  prev.pdf_text || "",
  prev.ocr_text || ""
].filter(Boolean).join("\n");

const fullText = [
  prev.message ? `User Message: ${prev.message}` : "",
  extractedText ? `Extracted Text: ${extractedText}` : ""
].filter(Boolean).join("\n\n");

return [
  {
    json: {
      ...prev,
      extracted_text: extractedText,
      fullText
    }
  }
];

const item = $input.first().json;

return [
  {
    json: {
      ...item,
      response: "Your issue has been logged and a support ticket has been created. Our team will contact you shortly."
    }
  }
];

